def unescape(s):
    return s.replace('\\n', '\n').replace('\\t', '\t')


grammars = set()
inputs_by_grammar = {}


def note(grammar, *inputs):
    grammars.add(grammar)
    inputs_by_grammar.setdefault(grammar, set()).update(inputs)


for block in DATA['validation/validate-grammar.test.ts'][0]['cases']:
    note(block, '')
for grammar, _pos, _reason in DATA['validation/validate-grammar.test.ts'][1]['cases']:
    note(grammar, '')
for grammar, inp in DATA['validation/validate-input.test.ts'][0]['cases']:
    note(grammar, inp)
for grammar, inp, _pos in DATA['validation/validate-input.test.ts'][1]['cases']:
    note(grammar, inp)
for grammar, _expected in DATA['iteration/iteration.test.ts'][0]['cases']:
    note(grammar, '')
for grammar, inp, _expected in DATA['iteration/iteration-with-an-initial-string.test.ts'][0]['cases']:
    note(grammar, inp)
for grammar, a, b in DATA['iteration/iteration-with-additional-strings.test.ts'][0]['cases']:
    note(grammar, a + b)
for grammar, a, b, _e in DATA['iteration/iteration-with-additional-strings.test.ts'][1]['cases']:
    note(grammar, a + b)
for _name, case, grammar in DATA['iteration/grammars.test.ts'][0]['cases']:
    note(unescape(grammar), unescape(case))

# Fuzz: random inputs drawn from an alphabet skewed toward characters the grammar mentions.
rng = random.Random(20260909)
for grammar in list(grammars):
    alphabet = sorted(set(grammar) | set('abz09 \n+-*/=()[]{}"'))
    for _ in range(20):
        length = rng.randint(1, 14)
        inputs_by_grammar[grammar].add(''.join(rng.choice(alphabet) for _ in range(length)))

cases = []
for grammar in sorted(grammars):
    for inp in sorted(inputs_by_grammar[grammar]):
        cases.append({'grammar': grammar, 'input': inp})

print(f'{len(cases)} differential cases')
with open('/tmp/ref/in.json', 'w') as f:
    json.dump(cases, f)

subprocess.run(
    ['node', '--experimental-transform-types', 'run.mjs', 'in.json', 'out.json'],
