)
with open('/tmp/ref/out.json') as f:
    expected = json.load(f)


def run_python(grammar, input_):
    try:
        state = GBNF(grammar)
        steps = [[rule.to_dict() for rule in state]]
        for ch in input_:
            state = state.add(ch)
            steps.append([rule.to_dict() for rule in state])
        return {'ok': True, 'steps': steps}
    except Exception as err:  # noqa: BLE001 - mirroring the JS harness
        return {'ok': False, 'name': type(err).__name__, 'message': str(err)}


mismatches = []
for case, exp in zip(cases, expected):
    got = run_python(case['grammar'], case['input'])
    if got != exp:
        mismatches.append((case, exp, got))

print(f'{len(mismatches)} mismatches')
for case, exp, got in mismatches[:10]:
    print('---')
    print('grammar:', repr(case['grammar']))
    print('input:  ', repr(case['input']))
    print('ref:    ', json.dumps(exp)[:400])
    print('port:   ', json.dumps(got)[:400])
sys.exit(1 if mismatches else 0)

